            adj[b].append((a, c))

        visited = [False] * (n + 1)
        x = [0.0] * (n + 1)
        possible = True

        for i in range(1, n + 1):
            if visited[i]:
                continue

            visited[i] = True
            x[i] = 0.0

            stack = [i]
            order = []
            parents = {}

            idx = 0
            while idx < len(stack):
                u = stack[idx]
                idx += 1
                order.append(u)

                for v, c in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        parents[v] = u
                        stack.append(v)

        system = []
        variables = []

