        if n == 0:
            return 0
        result = 0
        d = 1
        while True:
            start = 10 ** (d - 1)
            end = min(n, 10 ** d - 1)
            if start > end:
                break
            count = end - start + 1
            result += count * d
            d += 1
            if d > 18:
